/** Mirrors PortfolioAPI.Core.DTOs.ProjectMetricDto. */
export interface ProjectMetric {
  labelEn: string;
  labelAr: string;
  value: string;
}

/**
 * Mirrors PortfolioAPI.Core.DTOs.ProjectDto (api/Projects, api/public/projects).
 * The API is bilingual — En fields are the display values used by the English dashboard.
 */
export interface Project {
  id: number;
  /** Stable public link id - generated by the API, never changed by a rename. */
  slug: string;
  titleEn: string;
  titleAr: string;
  descriptionEn: string;
  descriptionAr: string;
  imageUrl: string | null;
  technologies: string[];
  githubUrl: string | null;
  liveUrl: string | null;
  featured: boolean;
  order: number;
  isActive: boolean;
  /** Editorial fields consumed by the public portfolio (filters, chips, badges). */
  categoryEn: string | null;
  categoryAr: string | null;
  clientEn: string | null;
  clientAr: string | null;
  typeEn: string | null;
  typeAr: string | null;
  databaseEn: string | null;
  databaseAr: string | null;
  statusEn: string | null;
  statusAr: string | null;
  badgesEn: string[];
  badgesAr: string[];
  metricsEn: ProjectMetric[];
  metricsAr: ProjectMetric[];
  gradient: string | null;
  createdAt: string;
  updatedAt: string | null;
}

/** Payload accepted by POST/PUT api/Projects — mirrors PortfolioAPI.Core.DTOs.CreateProjectDto. */
export interface ProjectPayload {
  titleEn: string;
  titleAr: string;
  descriptionEn: string;
  descriptionAr: string;
  imageUrl?: string | null;
  technologies?: string[];
  githubUrl?: string | null;
  liveUrl?: string | null;
  featured?: boolean;
  order?: number;
  isActive?: boolean;
  categoryEn?: string | null;
  categoryAr?: string | null;
  clientEn?: string | null;
  clientAr?: string | null;
  typeEn?: string | null;
  typeAr?: string | null;
  databaseEn?: string | null;
  databaseAr?: string | null;
  statusEn?: string | null;
  statusAr?: string | null;
  badgesEn?: string[];
  badgesAr?: string[];
  metricsEn?: ProjectMetric[];
  metricsAr?: ProjectMetric[];
  gradient?: string | null;
}
